Please audit the security of this excerpt from our multi-tenant B2B invoicing SaaS (Node 22, Express 4, PostgreSQL, JWT auth, deployed behind a load balancer). Every customer company is a tenant; users belong to exactly one tenant.

// middleware/auth.js
const JWT_SECRET = process.env.JWT_SECRET || 'changeme-dev-secret';
function requireAuth(req, res, next) {
  try {
    req.user = jwt.verify(req.headers.authorization?.split(' ')[1], JWT_SECRET); // { id, tenantId, role }
    next();
  } catch { res.sendStatus(401); }
}

// routes/invoices.js
router.get('/invoices/:id', requireAuth, async (req, res) => {
  const r = await db.query('SELECT * FROM invoices WHERE id = $1', [req.params.id]);
  if (!r.rows[0]) return res.sendStatus(404);
  res.json(r.rows[0]);
});
router.post('/invoices/:id/pay', requireAuth, async (req, res) => {
  const r = await db.query('SELECT * FROM invoices WHERE id = $1 AND tenant_id = $2', [req.params.id, req.user.tenantId]);
  if (!r.rows[0]) return res.sendStatus(404);
  await payments.charge(r.rows[0]);
  res.sendStatus(202);
});

// routes/profile.js
router.post('/avatar', requireAuth, upload.single('file'), (req, res) => {
  fs.renameSync(req.file.path, path.join(__dirname, '../public/avatars', req.file.originalname));
  res.json({ url: '/avatars/' + req.file.originalname });
});

Invoice IDs are sequential integers. public/ is served statically on the main app domain.

